const schema365 = {"type":"object","title":"Rating","description":"A methodology-neutral assessment of risk along likelihood and impact, with an overall score. The same shape expresses inherent, residual, and target risk so reductions can be compared. A rating can be qualitative (a `level`), semi-quantitative (a numeric `score` on a bounded scale), or quantitative (for example a probable monetary loss under [FAIR](https://www.fairinstitute.org/)). For a catalogue of assessment techniques, see [IEC 31010](https://www.iso.org/standard/72140.html).","additionalProperties":false,"properties":{"likelihood":{"$ref":"#/$defs/cyclonedx-risk-2.0/$defs/likelihood"},"impacts":{"type":"array","title":"Impacts","uniqueItems":true,"minItems":1,"description":"The impacts of the risk in this rating. A rating may carry more than one impact, for example a harm and a benefit for the same affected group, each with its own polarity and categories.","items":{"$ref":"#/$defs/cyclonedx-risk-2.0/$defs/impact"}},"score":{"$ref":"#/$defs/cyclonedx-risk-2.0/$defs/riskScore"},"detectability":{"type":"object","title":"Detectability","additionalProperties":false,"description":"The ease or likelihood of detecting the event before or as it is realized, used as a third axis by methodologies such as [FMEA](https://asq.org/quality-resources/fmea), whose risk priority number multiplies severity, occurrence, and detection.","properties":{"score":{"type":"number","minimum":0,"description":"The detection value on the scale defined by the methodology. For FMEA, a higher value indicates that the event is harder to detect and therefore riskier."},"description":{"type":"string","description":"A narrative explanation of the detectability assessment."}}},"controllability":{"type":"object","title":"Controllability","additionalProperties":false,"description":"The ability of the people involved to avoid the harm once the event occurs, used as a third axis by functional safety methodologies such as the hazard analysis and risk assessment of [ISO 26262](https://www.iso.org/standard/68383.html), which derives an integrity level from severity, exposure, and controllability.","properties":{"score":{"type":"number","minimum":0,"description":"The controllability value on the scale defined by the methodology. For ISO 26262, a higher class indicates that the harm is harder to avoid."},"description":{"type":"string","description":"A narrative explanation of the controllability assessment."}}},"confidence":{"type":"number","minimum":0,"maximum":1,"title":"Confidence","description":"Confidence in this rating, expressed as a decimal from 0 to 1, where 1 is full confidence. Supports quantitative methods that reason over uncertainty."},"rationale":{"type":"string","title":"Rationale","description":"The justification for this rating, including the method and the evidence considered."}}};
const schema366 = {"type":"object","required":["level"],"additionalProperties":false,"properties":{"level":{"enum":["negligible","low","moderate","major","catastrophic"],"description":"The qualitative impact severity level.","meta:enum":{"negligible":"Minimal impact with no significant consequences.","low":"Minor impact with limited consequences.","moderate":"Moderate impact affecting some operations.","major":"Significant impact with serious consequences.","catastrophic":"Catastrophic impact with existential consequences."}},"polarity":{"title":"Polarity","description":"Whether the impact represents a harm or a benefit. Benefits support modeling opportunities and positive risk.","enum":["harm","benefit"],"meta:enum":{"harm":"A negative impact or downside.","benefit":"A positive impact or upside."}},"score":{"type":"number","minimum":0,"description":"Numeric impact score on the scale defined by the methodology."},"categories":{"type":"array","uniqueItems":true,"items":{"$ref":"#/$defs/cyclonedx-risk-2.0/$defs/impactCategory"},"description":"The categories of impact, including harms relevant to AI and societal risk."},"factors":{"type":"array","title":"Factors","items":{"$ref":"#/$defs/cyclonedx-risk-2.0/$defs/impactFactor"},"description":"The factors considered when determining the impact, allowing methodologies that derive impact from multiple weighted dimensions to record the breakdown."},"range":{"$ref":"#/$defs/cyclonedx-risk-2.0/$defs/estimateRange","description":"A range for the impact score, supporting quantitative methods that reason over distributions."},"riskAttributes":{"type":"array","items":{"$ref":"#/$defs/cyclonedx-risk-2.0/$defs/riskAttribute"},"description":"The risk attributes affected."},"quantification":{"$ref":"#/$defs/cyclonedx-risk-2.0/$defs/impactQuantification"},"description":{"type":"string","description":"A description of the potential impact."},"methodology":{"$ref":"#/$defs/cyclonedx-risk-2.0/$defs/riskMethodology","description":"The methodology used to derive this impact rating, where the impact is rated on its own, for example on a damage scenario before any risk is scored."}}};
const schema367 = {"title":"Impact Category","description":"A category of impact, including harms relevant to AI and societal risk. The security and privacy attributes compromised, such as confidentiality or integrity, are recorded as risk attributes rather than as impact categories. Use the custom option for categories specific to an organization's risk taxonomy.","oneOf":[{"title":"Predefined Impact Category","enum":["financial","reputation","regulatory","safety","privacy","operational","strategic","discrimination","fairness","human-rights","environmental","societal","psychological","physical","health"],"meta:enum":{"financial":"Financial loss or impact.","reputation":"Reputational damage.","regulatory":"Regulatory compliance impact.","safety":"Human safety impact.","privacy":"Privacy violation impact.","operational":"Operational disruption, including degraded performance, reliability, or correctness of a system or its outputs.","strategic":"Strategic business impact.","discrimination":"Unfair treatment of individuals or groups, including on the basis of protected attributes.","fairness":"Impact on the fair and equitable treatment of affected groups.","human-rights":"Impact on fundamental human rights, including autonomy and dignity.","environmental":"Environmental impact, including energy use and carbon emissions.","societal":"Impact on society, communities, or civic processes.","psychological":"Psychological or emotional harm.","physical":"Physical harm to people or property.","health":"Impact on physical or mental health."}},{"title":"Custom Impact Category","type":"object","required":["name"],"additionalProperties":false,"properties":{"name":{"type":"string","minLength":1,"title":"Name","description":"The name of the custom impact category."},"description":{"type":"string","title":"Description","description":"A description of the custom impact category."}}}]};
